function solve(s) {
  let i = 0;
  function decode() {
    let out = '', num = 0;
    while (i < s.length && s[i] !== ']') {
      if (s[i] >= '0' && s[i] <= '9') num = num * 10 + +s[i++];
      else if (s[i] === '[') { i++; out += decode().repeat(num); num = 0; }
      else out += s[i++];
    }
    i++;
    return out;
  }
  return decode();
}

function solve(s) {
  const countStack = [], strStack = [];
  let cur = '', k = 0;
  for (const ch of s) {
    if (ch >= '0' && ch <= '9') k = k * 10 + +ch;
    else if (ch === '[') { countStack.push(k); strStack.push(cur); cur = ''; k = 0; }
    else if (ch === ']') { const prev = strStack.pop(), n = countStack.pop(); cur = prev + cur.repeat(n); }
    else cur += ch;
  }
  return cur;
}

